/* Pixel Passport — offline-first demo mode. Every record has a stable ID. */
const KEY='pixel-passport-v1';
const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const today=()=>new Date().toISOString().slice(0,10);
const money=(n,c='SGD')=>n==null?'Not entered':new Intl.NumberFormat('en-SG',{style:'currency',currency:c,maximumFractionDigits:0}).format(Number(n)||0);
const date=s=>s?new Date(`${s}T12:00:00`).toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric'}):'Date TBD';
const days=s=>s?Math.ceil((new Date(`${s}T00:00:00`)-new Date())/86400000):null;
const pct=(a,b)=>b?Math.round(a/b*100):0;
const places=[['St. Gallen','Switzerland',47.4245,9.3767,'🏡','planned'],['Paris','France',48.8566,2.3522,'🗼','wishlist'],['Rome','Italy',41.9028,12.4964,'🏛️','wishlist'],['Venice','Italy',45.4408,12.3155,'🚤','wishlist'],['Austria','Austria',47.5162,14.5501,'🏔️','wishlist'],['Slovenia','Slovenia',46.1512,14.9955,'🌲','wishlist'],['Athens','Greece',37.9838,23.7275,'🏺','wishlist'],['Finland','Finland',61.9241,25.7482,'❄️','wishlist']];
function seed(){const main=id(),family=id();return {version:1,profile:{name:'Traveler',baseCurrency:'SGD',exchangeBudget:'',weightTarget:20},trips:[{id:main,name:'Europe Exchange 2027',status:'draft',start:'2027-01-13',end:'',notes:'University of St. Gallen exchange, approximately January–May 2027. All stops are tentative.',budget:'',focus:'Skiing, winter adventures and cultural sightseeing'},{id:family,name:'End-of-Exchange Family Trip',status:'draft',start:'',end:'',notes:'Approximately two weeks in late May. Final destination: Switzerland. Exact dates and route TBD.',budget:'',focus:'Family travel'}],destinations:[...places.map((p,i)=>({id:id(),tripId:main,name:p[0],country:p[1],lat:p[2],lng:p[3],icon:p[4],status:p[5],arrival:'',departure:'',notes:i===0?'Exchange home base':'' ,order:i})),{id:id(),tripId:family,name:'Switzerland',country:'Switzerland',lat:46.8182,lng:8.2275,icon:'🏔️',status:'wishlist',arrival:'',departure:'',notes:'Final destination; exact city TBD',order:0}],activities:[],tasks:[],packing:[],expenses:[],bookings:[],skiTrips:[],journal:[],dismissed:[],rates:null,ratesUpdated:null};}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}
let page=location.hash.slice(1).split('/')[0]||'home',selectedTrip=state.trips[0]?.id,selectedDestination=null,view='timeline',map=null,mapMarkers=[],filters={};
const nav=[['home','Adventure Home','🏡'],['trips','My Trips & Itinerary','🧭'],['map','World Map','🗺️'],['packing','Packing Inventory','🎒'],['tasks','Quest Board','📜'],['budget','Budget & Expenses','💰'],['bookings','Booking Vault','🎫'],['ski','Ski Planner','⛷️'],['journal','Travel Journal','📖'],['settings','Settings','⚙️']];
const statuses=['wishlist','planned','booked','visited'];
const activityTypes=['sightseeing','skiing','food','transport','accommodation','shopping','other'];
const taskTypes=['flights','accommodation','university administration','visas','transport','skiing','shopping','packing','personal'];
const expenseTypes=['flights','trains','accommodation','food','activities','skiing','shopping','insurance','miscellaneous'];
const currencies=['SGD','EUR','CHF','GBP','USD'];
const tripName=id=>state.trips.find(x=>x.id===id)?.name||'Unassigned';
const destName=id=>state.destinations.find(x=>x.id===id)?.name||'Unassigned';
const option=(items,value)=>items.map(x=>`<option value="${esc(typeof x==='string'?x:x.id)}" ${String(typeof x==='string'?x:x.id)===String(value)?'selected':''}>${esc(typeof x==='string'?x:x.name)}</option>`).join('');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('Storage is full. Export a backup from Settings.')}render()}
function toast(s){const t=$('#toast');t.insertAdjacentHTML('beforeend',`<div>${esc(s)}</div>`);setTimeout(()=>t.firstElementChild?.remove(),3400)}
function go(p){location.hash=p;page=p;selectedDestination=null;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1).split('/')[0]||'home';render()});
function confirmDelete(collection,recordId,label){let detail='';if(collection==='destinations'){const n=state.activities.filter(x=>x.destinationId===recordId).length;detail=` ${n} linked activities will also be deleted. Bookings, expenses, tasks and ski plans will be kept with no destination.`}if(collection==='trips'){const n=state.destinations.filter(x=>x.tripId===recordId).length;detail=` ${n} destinations will move to your remaining trip.`}if(!confirm(`Delete ${label}?${detail}`))return;state[collection]=state[collection].filter(x=>x.id!==recordId);if(collection==='destinations'){state.activities=state.activities.filter(x=>x.destinationId!==recordId);for(const key of ['bookings','expenses','tasks','skiTrips','journal'])state[key].filter(x=>x.destinationId===recordId).forEach(x=>x.destinationId='')}if(collection==='trips'){const replacement=state.trips[0]?.id||'';for(const key of ['destinations','bookings','expenses','tasks','skiTrips','packing'])state[key].filter(x=>x.tripId===recordId).forEach(x=>x.tripId=replacement)}save();toast(`${label} deleted`)}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input class="field" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(name,label,opts,value='',extra=''){return `<label>${label}<select class="field" name="${name}" ${extra}>${option(opts,value)}</select></label>`}
function textField(name,label,value='',rows=3){return `<label class="full">${label}<textarea class="field" name="${name}" rows="${rows}">${esc(value)}</textarea></label>`}
function modal(title,body,onSave,submit='Save changes'){const root=$('#modal-root');root.innerHTML=`<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="btn small close" type="button" data-close>✕</button><h2>${esc(title)}</h2><form id="dialog-form"><div class="form-grid">${body}</div><div class="form-actions"><button class="btn ghost" type="button" data-close>Cancel</button><button class="btn primary" type="submit">${esc(submit)}</button></div></form></div></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);$('.modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal()};$('#dialog-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const ok=await onSave(Object.fromEntries(fd));if(ok!==false){closeModal();save();toast('Saved!')}}catch(err){toast(err.message||'Could not save')}};root.querySelector('input,select,textarea')?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
function shell(content){const title=nav.find(x=>x[0]===page)?.[1]||'Adventure Home';$('#app').innerHTML=`<div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">✈️</div><div><strong>PIXEL<br>PASSPORT</strong><small>every journey is an adventure</small></div></div><div><div class="sidebar-label">Your adventure</div><nav class="nav">${nav.map(([key,label,icon])=>`<button data-nav="${key}" class="${page===key?'active':''}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav></div><div class="sidebar-bottom tiny-card"><div class="row"><span style="font-size:25px">🧑‍✈️</span><strong>Explorer Lv. ${level()}</strong></div><div class="progress" style="margin-top:10px"><span style="width:${xp()%100}%"></span></div><p>${xp()} XP · ${100-xp()%100} XP to next level</p></div></aside><main class="main"><header class="topbar"><div class="row"><button class="btn icon mobile-menu" id="menu-btn" aria-label="Open menu">☰</button><div><div class="eyebrow">✦ THE TRAVEL LOG ✦</div><h1>${esc(title)}</h1></div></div><div class="top-actions"><span class="mode-chip">● Demo mode · saved on this device</span><span class="avatar-chip" title="Your travel companion">🧑‍✈️</span></div></header>${content}</main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$('#menu-btn').onclick=()=>$('#sidebar').classList.toggle('open')}
const xp=()=>state.tasks.filter(x=>x.done).length*25+state.destinations.filter(x=>x.status==='visited').length*50;
const level=()=>Math.floor(xp()/100)+1;
const packed=()=>state.packing.filter(x=>x.status==='packed').length;
function progressSummary(){const total=state.tasks.length+state.packing.length+state.destinations.filter(x=>x.status!=='wishlist').length;const done=state.tasks.filter(x=>x.done).length+packed()+state.destinations.filter(x=>x.status==='booked'||x.status==='visited').length;return pct(done,total)}
function nextTrip(){return [...state.trips].filter(x=>x.start&&days(x.start)>=0).sort((a,b)=>a.start.localeCompare(b.start))[0]}
function header(title,sub,button,action){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${button?`<button class="btn small primary" data-action="${action}">${button}</button>`:''}</div>`}
function bindActions(root=document){root.querySelectorAll('[data-action]').forEach(el=>{el.addEventListener('click',()=>actions[el.dataset.action]?.(el.dataset))})}
const actions={};
function render(){if(map){map.remove();map=null}const fn={home:homePage,trips:tripsPage,map:mapPage,packing:packingPage,tasks:tasksPage,budget:budgetPage,bookings:bookingsPage,ski:skiPage,journal:journalPage,settings:settingsPage}[page]||homePage;shell(fn());bindActions();if(page==='map')setTimeout(initMap,0)}
function homePage(){const nt=nextTrip(),upcoming=[...state.tasks].filter(x=>!x.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4),dest=state.destinations.filter(x=>x.status!=='visited').slice(0,4),base=state.profile.baseCurrency,actual=convertedExpenses().sum,budget=Number(state.profile.exchangeBudget)||0;return `<section class="hero"><div class="cloud one"></div><div class="cloud two"></div><div class="mountain back"></div><div class="mountain"></div><div class="ground"></div><div class="pixel-train">🚞</div><div class="hero-stamp">LET'S<br>EXPLORE<br>✦</div><div class="hero-content"><div class="eyebrow">✦ YOUR ADVENTURE AWAITS ✦</div><h2>Welcome back,<br>${esc(state.profile.name)}!</h2><p>From St. Gallen to everywhere — your next chapter is taking shape, one little quest at a time.</p><button class="btn primary" data-action="newDestination">＋ Plan a destination</button></div></section><div class="grid four"><div class="card stat"><div class="iconbox">⏳</div><div class="stat-label">Next adventure</div><div class="stat-value">${nt?days(nt.start)+' days':'TBD'}</div><div class="stat-note">${nt?esc(nt.name):'Add a trip date'}</div></div><div class="card stat"><div class="iconbox">🧭</div><div class="stat-label">Planning progress</div><div class="stat-value">${progressSummary()}%</div><div class="progress"><span style="width:${progressSummary()}%"></span></div></div><div class="card stat"><div class="iconbox">🎒</div><div class="stat-label">Bag packed</div><div class="stat-value">${pct(packed(),state.packing.length)}%</div><div class="stat-note">${packed()} of ${state.packing.length} items</div></div><div class="card stat"><div class="iconbox">💰</div><div class="stat-label">Actual spending</div><div class="stat-value" style="font-size:20px">${money(actual,base)}</div><div class="stat-note">${budget?'of '+money(budget,base)+' budget':'Set a budget to track progress'}</div></div></div><div class="grid two"><div>${header('📍 Upcoming destinations','Your route can always change','View itinerary','goTrips')}<div class="card">${dest.length?dest.map(d=>`<div class="list-row"><div class="row"><span class="place-icon">${d.icon||'📍'}</span><div><strong>${esc(d.name)}, ${esc(d.country)}</strong><small>${esc(tripName(d.tripId))} · ${date(d.arrival)}</small></div></div><span class="pill ${d.status==='wishlist'?'lav':''}">${esc(d.status)}</span></div>`).join(''):'<div class="empty">Your route is waiting for its first stop.</div>'}</div></div><div>${header('📜 Quest board','The next little steps','All quests','goTasks')}<div class="card">${upcoming.length?upcoming.map(t=>`<div class="list-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.category)} · ${date(t.due)}</small></div><span class="pill ${t.priority==='high'?'pink':''}">${esc(t.priority||'normal')}</span></div>`).join(''):'<div class="empty"><div class="big">✨</div>No active quests yet. Add one when you are ready.</div>'}</div></div></div>${header('🗺️ Your adventure at a glance','The map grows with every destination')}<div class="grid three"><div class="card soft-blue"><div style="font-size:32px">🗺️</div><h3>${state.destinations.length} places on your map</h3><p class="muted">Wishlist, planned, booked and visited places together.</p><button class="btn small" data-action="goMap">Explore map →</button></div><div class="card soft-pink"><div style="font-size:32px">📘</div><h3>${new Set(state.destinations.filter(x=>x.status==='visited').map(x=>x.country)).size} passport stamps</h3><p class="muted">Mark a destination visited to unlock its country stamp.</p><button class="btn small" data-action="goJournal">Open journal →</button></div><div class="card soft-yellow"><div style="font-size:32px">🧑‍✈️</div><h3>A note from Pip</h3><p class="muted">${state.tasks.some(x=>!x.done&&x.due&&days(x.due)<0)?'A quest is overdue. Let’s take care of it together!':'There’s no perfect route. The fun is in discovering yours.'}</p><button class="btn small" data-action="goPacking">Check your bag →</button></div></div>`}
Object.assign(actions,{goTrips:()=>go('trips'),goTasks:()=>go('tasks'),goMap:()=>go('map'),goJournal:()=>go('journal'),goPacking:()=>go('packing')});
function tripsPage(){const trip=state.trips.find(x=>x.id===selectedTrip)||state.trips[0];selectedTrip=trip?.id;const ds=state.destinations.filter(x=>x.tripId===trip?.id).sort((a,b)=>a.order-b.order);let body=`${header('🧳 Your trips','Draft plans stay flexible','＋ New trip','newTrip')}<div class="grid two">${state.trips.map(t=>`<div class="trip-card" style="border-color:${t.id===selectedTrip?'#78a989':''}"><div class="row between"><span class="pill ${t.status==='draft'?'yellow':''}">${esc(t.status)}</span><div class="row"><button class="btn small icon" data-action="editTrip" data-id="${t.id}" aria-label="Edit trip">✎</button><button class="btn small icon" data-action="deleteTrip" data-id="${t.id}" aria-label="Delete trip">🗑</button></div></div><h3>${esc(t.name)}</h3><p>${date(t.start)} – ${date(t.end)} · ${state.destinations.filter(d=>d.tripId===t.id).length} stops</p><button class="btn small ${t.id===selectedTrip?'primary':''}" data-action="selectTrip" data-id="${t.id}">${t.id===selectedTrip?'Viewing route':'View route →'}</button></div>`).join('')}</div>`;if(!trip)return body;body+=`${header('🚞 '+esc(trip.name)+' route',esc(trip.notes),'＋ Add destination','newDestination')}<div class="toolbar"><select id="trip-select" class="field" style="max-width:240px" aria-label="Choose trip">${option(state.trips,selectedTrip)}</select><span class="pill yellow">Draft itinerary · dates flexible</span><span class="muted small-text">${ds.length} stops · estimated activity cost ${money(state.activities.filter(a=>ds.some(d=>d.id===a.destinationId)).reduce((s,a)=>s+(Number(a.cost)||0),0),'SGD')} (entered SGD only)</span></div><div class="grid three">${ds.map((d,i)=>`<article class="destination-card"><div class="art">${d.icon||'📍'}</div><div class="row between"><div><h3>${esc(d.name)}</h3><span class="muted small-text">${esc(d.country)}</span></div><span class="pill ${d.status==='wishlist'?'lav':d.status==='booked'?'pink':''}">${esc(d.status)}</span></div><div class="small-text muted">${date(d.arrival)} → ${date(d.departure)} · ${state.activities.filter(a=>a.destinationId===d.id).length} activities</div><div class="actions"><button class="btn small primary" data-action="openDestination" data-id="${d.id}">Open</button><button class="btn small icon" data-action="editDestination" data-id="${d.id}" aria-label="Edit ${esc(d.name)}">✎</button><button class="btn small icon" data-action="moveDestination" data-id="${d.id}" data-direction="-1" aria-label="Move earlier">←</button><button class="btn small icon" data-action="moveDestination" data-id="${d.id}" data-direction="1" aria-label="Move later">→</button><button class="btn small icon" data-action="duplicateDestination" data-id="${d.id}" aria-label="Duplicate">⧉</button><button class="btn small icon" data-action="deleteDestination" data-id="${d.id}" aria-label="Delete">🗑</button></div></article>`).join('')}</div>${ds.length?'':'<div class="empty">No stops in this trip yet. Add one to begin your route.</div>'}`;if(selectedDestination){const d=state.destinations.find(x=>x.id===selectedDestination);if(d)body+=destinationDetail(d)}return body}
function destinationDetail(d){const activities=state.activities.filter(x=>x.destinationId===d.id).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)||a.order-b.order),bookings=state.bookings.filter(x=>x.destinationId===d.id),expenses=state.expenses.filter(x=>x.destinationId===d.id),skis=state.skiTrips.filter(x=>x.destinationId===d.id);return `${header('📍 '+esc(d.name)+' details',esc(d.country)+' · '+date(d.arrival)+' – '+date(d.departure),'＋ Activity','newActivity')}<div class="toolbar"><div class="tabset">${['timeline','list','calendar'].map(x=>`<button data-action="setView" data-value="${x}" class="${view===x?'active':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><select id="activity-type-filter" class="field" style="max-width:180px" aria-label="Filter activities"><option value="">All types</option>${option(activityTypes,filters.activityType)}</select><select id="activity-status-filter" class="field" style="max-width:180px" aria-label="Filter activity status"><option value="">All statuses</option>${option(['idea','planned','booked','completed','cancelled'],filters.activityStatus)}</select></div><div class="grid two"><div class="card"><h3>Day-by-day plan</h3>${activityList(activities.filter(a=>(!filters.activityType||a.type===filters.activityType)&&(!filters.activityStatus||a.status===filters.activityStatus)))}</div><div class="stack"><div class="card soft-blue"><h3>🏡 Stay & transport</h3>${bookings.length?bookings.map(b=>`<div class="list-row"><div><strong>${esc(b.provider||b.type)}</strong><small>${esc(b.type)} · ${date(b.date)}</small></div><span class="pill">${esc(b.status)}</span></div>`).join(''):'<p class="muted">No bookings recorded. Details are not yet entered.</p>'}<button class="btn small" data-action="newBooking" data-destination="${d.id}">＋ Add booking</button></div><div class="card soft-yellow"><h3>💰 Expenses & notes</h3><p>${expenses.length} recorded expenses · ${skis.length} ski plans</p><p class="muted">${esc(d.notes||'No notes yet. Add what you want to remember.')}</p><button class="btn small" data-action="editDestination" data-id="${d.id}">Edit notes</button></div><div class="card"><h3>⛅ Weather</h3><p class="muted">Forecasts are available near the travel date. Use the live weather button to check current conditions.</p><button class="btn small" data-action="weather" data-id="${d.id}">Check current weather</button><div id="weather-result-${d.id}" class="small-text muted" style="margin-top:10px"></div></div></div></div>`}
function activityList(items){if(!items.length)return '<div class="empty">No activities yet. Add an idea, booking, or memory to this stop.</div>';if(view==='calendar'){const grouped=Object.groupBy?Object.groupBy(items,a=>a.date||'Date TBD'):items.reduce((o,a)=>((o[a.date||'Date TBD']??=[]).push(a),o),{});return Object.entries(grouped).map(([day,arr])=>`<h4>${day==='Date TBD'?day:date(day)}</h4>${arr.map(activityRow).join('')}`).join('')}return `<div class="${view==='timeline'?'timeline':''}">${items.map(a=>view==='timeline'?`<div class="timeline-item"><div class="timeline-date">${a.date?date(a.date):'Date TBD'}<br>${esc(a.time||'')}</div><div class="timeline-content">${activityRow(a)}</div></div>`:activityRow(a)).join('')}</div>`}
function activityRow(a){return `<div class="list-row" draggable="true" data-drag-activity="${a.id}"><div><strong>${esc(a.title)}</strong><small>${esc(a.type)} · ${esc(a.status)}${a.cost?' · est. '+money(a.cost,a.currency||'SGD'):''}</small>${a.notes?`<small>${esc(a.notes)}</small>`:''}</div><div class="row"><button class="btn small icon" data-action="editActivity" data-id="${a.id}" aria-label="Edit activity">✎</button><button class="btn small icon" data-action="deleteActivity" data-id="${a.id}" aria-label="Delete activity">🗑</button></div></div>`}
function tripForm(record){const t=record||{};modal(record?'Edit trip':'New trip',field('name','Trip name',t.name,'text','required')+selectField('status','Status',['draft','planned','booked','completed'],t.status||'draft')+field('start','Start date',t.start,'date')+field('end','End date',t.end,'date')+field('budget','Budget (base currency)',t.budget,'number','min="0" step="0.01"')+field('focus','Travel focus',t.focus)+textField('notes','Notes',t.notes),v=>{if(v.start&&v.end&&v.end<v.start)throw Error('End date must be after start date');if(record)Object.assign(record,v);else{const x={id:id(),...v};state.trips.push(x);selectedTrip=x.id}})}
function destinationForm(record){const d=record||{};modal(record?'Edit destination':'New destination',field('name','City or place',d.name,'text','required')+field('country','Country',d.country,'text','required')+selectField('tripId','Trip',state.trips,d.tripId||selectedTrip)+selectField('status','Status',statuses,d.status||'wishlist')+field('arrival','Arrival date',d.arrival,'date')+field('departure','Departure date',d.departure,'date')+field('lat','Latitude',d.lat,'number','step="any" required')+field('lng','Longitude',d.lng,'number','step="any" required')+field('icon','Map icon / emoji',d.icon||'📍')+textField('notes','Notes',d.notes)+`<div class="full notice">Find coordinates with the Lookup button below. Adding a destination updates the map and offers related packing and quest suggestions.</div><button type="button" class="btn small full" id="lookup-place">🔎 Look up coordinates</button>`,v=>{const lat=Number(v.lat),lng=Number(v.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)throw Error('Enter valid coordinates');if(v.arrival&&v.departure&&v.departure<v.arrival)throw Error('Departure must be after arrival');if(record)Object.assign(record,{...v,lat,lng});else state.destinations.push({id:id(),...v,lat,lng,order:state.destinations.filter(x=>x.tripId===v.tripId).length})});$('#lookup-place').onclick=async()=>{const f=$('#dialog-form'),q=`${f.elements.name.value}, ${f.elements.country.value}`;if(!f.elements.name.value)return toast('Enter a place name first');$('#lookup-place').textContent='Looking up…';try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`);const j=await r.json();if(!j.length)throw Error('Place not found');f.elements.lat.value=j[0].lat;f.elements.lng.value=j[0].lon;toast('Coordinates found')}catch(e){toast(e.message||'Lookup unavailable. Enter coordinates manually.')}$('#lookup-place').textContent='🔎 Look up coordinates'}
}
function activityForm(record){const a=record||{};modal(record?'Edit activity':'New activity',selectField('destinationId','Destination',state.destinations,a.destinationId||selectedDestination)+field('title','Activity',a.title,'text','required')+selectField('type','Category',activityTypes,a.type||'sightseeing')+selectField('status','Status',['idea','planned','booked','completed','cancelled'],a.status||'idea')+field('date','Date',a.date,'date')+field('time','Time',a.time,'time')+field('address','Address',a.address)+field('cost','Estimated cost',a.cost,'number','min="0" step="0.01"')+selectField('currency','Currency',currencies,a.currency||'SGD')+field('bookingLink','Booking link',a.bookingLink,'url')+textField('notes','Description & notes',a.notes),v=>{if(record)Object.assign(record,v);else state.activities.push({id:id(),order:state.activities.length,...v})})}
Object.assign(actions,{newTrip:()=>tripForm(),editTrip:({id})=>tripForm(state.trips.find(x=>x.id===id)),deleteTrip:({id})=>{if(state.trips.length===1)return toast('Keep at least one trip');confirmDelete('trips',id,tripName(id))},selectTrip:({id})=>{selectedTrip=id;selectedDestination=null;render()},newDestination:()=>destinationForm(),editDestination:({id})=>destinationForm(state.destinations.find(x=>x.id===id)),deleteDestination:({id})=>confirmDelete('destinations',id,destName(id)),duplicateDestination:({id:did})=>{const d=state.destinations.find(x=>x.id===did);state.destinations.push({...d,id:id(),name:d.name+' copy',status:'wishlist',order:state.destinations.length});save();toast('Destination duplicated')},moveDestination:({id:did,direction})=>{const d=state.destinations.find(x=>x.id===did),arr=state.destinations.filter(x=>x.tripId===d.tripId).sort((a,b)=>a.order-b.order),i=arr.indexOf(d),j=i+Number(direction);if(j<0||j>=arr.length)return;[arr[i].order,arr[j].order]=[arr[j].order,arr[i].order];save()},openDestination:({id})=>{selectedDestination=id;render();setTimeout(()=>document.querySelector('.section-head:last-of-type')?.scrollIntoView({behavior:'smooth'}),0)},newActivity:()=>activityForm(),editActivity:({id})=>activityForm(state.activities.find(x=>x.id===id)),deleteActivity:({id})=>confirmDelete('activities',id,'activity'),setView:({value})=>{view=value;render()},weather:async({id:did})=>{const d=state.destinations.find(x=>x.id===did),el=$(`#weather-result-${did}`);el.textContent='Loading current weather…';try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${d.lat}&longitude=${d.lng}&current=temperature_2m,precipitation,wind_speed_10m`);if(!r.ok)throw Error();const j=await r.json();el.textContent=`Now: ${j.current.temperature_2m}°C · precipitation ${j.current.precipitation} mm · wind ${j.current.wind_speed_10m} km/h (Open-Meteo)`}catch{el.textContent='Weather unavailable right now.'}}});
function mapPage(){return `${header('🌍 World map','Real coordinates, movable map, and passport progress','＋ Add place','newDestination')}<div class="toolbar"><input id="map-search" class="field grow" placeholder="Search a city or country…" aria-label="Search map places"><button class="btn small" data-action="searchMap">🔎 Search</button><select id="map-trip" class="field" style="max-width:230px" aria-label="Filter by trip"><option value="">All trips</option>${option(state.trips,filters.mapTrip)}</select><select id="map-status" class="field" style="max-width:180px" aria-label="Filter by status"><option value="">All statuses</option>${option(statuses,filters.mapStatus)}</select></div><div class="map-shell"><div id="map-canvas" class="map-canvas"></div></div><div class="legend"><span><b>💜</b> Wishlist</span><span><b>💚</b> Planned</span><span><b>💗</b> Booked</span><span><b>⭐</b> Visited</span><span>Map data © OpenStreetMap contributors</span></div><div class="grid two"><div class="card"><h3>📍 Saved places</h3>${state.destinations.filter(d=>(!filters.mapTrip||d.tripId===filters.mapTrip)&&(!filters.mapStatus||d.status===filters.mapStatus)).map(d=>`<div class="list-row"><div><strong>${esc(d.name)}, ${esc(d.country)}</strong><small>${esc(tripName(d.tripId))}</small></div><button class="btn small" data-action="focusMap" data-id="${d.id}">View pin</button></div>`).join('')||'<div class="empty">No places match these filters.</div>'}</div><div class="card soft-lav"><h3>📘 Passport collection</h3><p class="muted">Visited countries unlock their stamps automatically.</p><div class="stamp-grid">${[...new Set(state.destinations.filter(x=>x.status==='visited').map(x=>x.country))].map(c=>`<div class="stamp"><div><span>✦</span><strong>${esc(c)}</strong></div></div>`).join('')||'<div class="empty" style="grid-column:1/-1">Your first stamp is waiting.</div>'}</div></div></div>`}
function initMap(){const node=$('#map-canvas');if(!node||map)return;if(!window.maplibregl){node.innerHTML='<div class="map-fallback"><div>🗺️<h3>Map tiles unavailable</h3><p>Your saved coordinates and places remain available below.</p></div></div>';return}try{map=new maplibregl.Map({container:node,style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'osm',type:'raster',source:'osm'}]},center:[9.4,47.4],zoom:3.7});map.addControl(new maplibregl.NavigationControl(),'top-right');map.on('load',()=>{const ds=state.destinations.filter(d=>(!filters.mapTrip||d.tripId===filters.mapTrip)&&(!filters.mapStatus||d.status===filters.mapStatus));const grouped=Object.groupBy?Object.groupBy(ds,d=>d.tripId):ds.reduce((o,d)=>((o[d.tripId]??=[]).push(d),o),{});const features=Object.values(grouped).flatMap(arr=>{const sorted=arr.filter(d=>d.status!=='wishlist').sort((a,b)=>a.order-b.order);return sorted.length>1?[{type:'Feature',geometry:{type:'LineString',coordinates:sorted.map(d=>[Number(d.lng),Number(d.lat)])}}]:[]});map.addSource('routes',{type:'geojson',data:{type:'FeatureCollection',features}});map.addLayer({id:'routes',type:'line',source:'routes',paint:{'line-color':'#d187a1','line-width':3,'line-dasharray':[2,2]}});ds.forEach(d=>{const el=document.createElement('button');el.className='map-pin';el.textContent={wishlist:'💜',planned:'💚',booked:'💗',visited:'⭐'}[d.status]||'📍';el.title=`${d.name}, ${d.country}`;el.style.cssText='border:0;background:transparent;cursor:pointer';el.onclick=()=>new maplibregl.Popup({offset:24}).setLngLat([Number(d.lng),Number(d.lat)]).setHTML(`<strong>${esc(d.name)}, ${esc(d.country)}</strong><br>${esc(d.status)} · ${esc(tripName(d.tripId))}<br><button onclick="window.openMapDestination('${d.id}')">Open itinerary →</button>`).addTo(map);mapMarkers.push(new maplibregl.Marker({element:el}).setLngLat([Number(d.lng),Number(d.lat)]).addTo(map))})})}catch(e){node.innerHTML='<div class="map-fallback">Map unavailable. Use the saved places below.</div>'}}
window.openMapDestination=did=>{selectedTrip=state.destinations.find(x=>x.id===did)?.tripId;selectedDestination=did;go('trips');selectedDestination=did;render()};
Object.assign(actions,{searchMap:async()=>{const q=$('#map-search')?.value.trim();if(!q)return;toast('Searching map…');try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`);const j=await r.json();if(!j.length)throw Error('Location not found');map?.flyTo({center:[Number(j[0].lon),Number(j[0].lat)],zoom:8});toast(j[0].display_name)}catch(e){toast(e.message||'Search unavailable')}},focusMap:({id:did})=>{const d=state.destinations.find(x=>x.id===did);map?.flyTo({center:[Number(d.lng),Number(d.lat)],zoom:8})}});
const packingSuggestions=()=>{const out=[];const add=(name,reason,category,icon,weight)=>{const key=name.toLowerCase();if(!state.packing.some(p=>p.name.toLowerCase()===key)&&!state.dismissed.includes(key)&&!out.some(p=>p.name===name))out.push({name,reason,category,icon,weight})};const winter=state.destinations.some(d=>['Switzerland','Austria','Finland','Slovenia'].includes(d.country))||state.trips.some(t=>t.start?.includes('-01-'));const ski=state.skiTrips.length||state.activities.some(a=>a.type==='skiing');if(winter){[['Warm coat','Cold-season destinations','checked luggage','🧥',1.2],['Thermal base layers','Winter travel','checked luggage','🧣',.4],['Waterproof shoes','Winter streets and snow','checked luggage','🥾',1]].forEach(x=>add(...x))}if(ski){[['Ski jacket and pants','Ski trip','checked luggage','🎿',1.5],['Waterproof gloves','Ski trip','checked luggage','🧤',.2],['Ski goggles','Ski trip','checked luggage','🥽',.2],['Ski socks','Ski trip','checked luggage','🧦',.15],['Helmet or rental reminder','Ski trip; rent locally if preferred','optional','⛑️',.7]].forEach(x=>add(...x))}if(state.destinations.length){[['Passport','International travel','personal bag','📘',.1],['Travel adapter','European destinations','cabin luggage','🔌',.1],['Reusable water bottle','City and day trips','personal bag','💧',.3]].forEach(x=>add(...x))}return out};
function packingPage(){const list=state.packing.filter(x=>(!filters.packBag||x.bag===filters.packBag)&&(!filters.packStatus||x.status===filters.packStatus)),suggestions=packingSuggestions(),weight=state.packing.filter(x=>x.status==='packed').reduce((s,p)=>s+(Number(p.weight)||0)*(Number(p.qty)||1),0);return `${header('🎒 Packing inventory','Every little item earns its place in your bag','＋ Add item','newPacking')}<div class="grid three"><div class="card soft-blue"><strong>${packed()} / ${state.packing.length} packed</strong><div class="progress" style="margin:10px 0"><span style="width:${pct(packed(),state.packing.length)}%"></span></div><span class="muted">${pct(packed(),state.packing.length)}% ready</span></div><div class="card soft-yellow"><strong>${weight.toFixed(1)} kg estimated</strong><p class="muted small-text">Packed items with weights entered · target ${state.profile.weightTarget||'not set'} kg</p></div><div class="card soft-lav"><strong>${suggestions.length} suggestions</strong><p class="muted small-text">Based on your saved destinations and activities</p></div></div><div class="toolbar"><select id="pack-bag" class="field" style="max-width:220px"><option value="">All bags</option>${option(['checked luggage','cabin luggage','personal bag','optional'],filters.packBag)}</select><select id="pack-status" class="field" style="max-width:220px"><option value="">All item statuses</option>${option(['needed','purchased','packed'],filters.packStatus)}</select></div><div class="inventory">${list.map(p=>`<div class="inventory-slot ${p.status==='packed'?'packed':''}"><input class="slot-check" type="checkbox" data-pack-check="${p.id}" ${p.status==='packed'?'checked':''} aria-label="Mark ${esc(p.name)} packed"><span class="emoji">${esc(p.icon||'🎒')}</span><strong>${esc(p.name)}</strong><small>×${p.qty||1} · ${esc(p.bag)} · ${esc(p.status)}</small><div class="slot-actions"><button class="btn small icon" data-action="editPacking" data-id="${p.id}" aria-label="Edit item">✎</button><button class="btn small icon" data-action="deletePacking" data-id="${p.id}" aria-label="Delete item">🗑</button></div></div>`).join('')}</div>${list.length?'':'<div class="empty">Your inventory is ready for items.</div>'}${header('✨ Suggested for your adventure','Accept only what you want to bring')}<div class="grid three">${suggestions.map((s,i)=>`<div class="suggestion"><strong>${s.icon} ${esc(s.name)}</strong><p>${esc(s.reason)}</p><div class="row"><button class="btn small primary" data-action="acceptPacking" data-index="${i}">＋ Add</button><button class="btn small ghost" data-action="dismissPacking" data-index="${i}">Dismiss</button></div></div>`).join('')||'<div class="empty">You have reviewed all current suggestions.</div>'}</div>`}
function packingForm(record){const p=record||{};modal(record?'Edit item':'Add packing item',field('name','Item name',p.name,'text','required')+field('icon','Icon / emoji',p.icon||'🎒')+field('qty','Quantity',p.qty||1,'number','min="1" required')+field('weight','Weight per item (kg)',p.weight,'number','min="0" step="0.01"')+selectField('bag','Bag',['checked luggage','cabin luggage','personal bag','optional'],p.bag||'checked luggage')+selectField('status','Status',['needed','purchased','packed'],p.status||'needed')+selectField('tripId','Trip',state.trips,p.tripId||selectedTrip)+textField('notes','Notes',p.notes),v=>{if(record)Object.assign(record,v);else state.packing.push({id:id(),...v})})}
Object.assign(actions,{newPacking:()=>packingForm(),editPacking:({id})=>packingForm(state.packing.find(x=>x.id===id)),deletePacking:({id})=>confirmDelete('packing',id,'packing item'),acceptPacking:({index})=>{const s=packingSuggestions()[Number(index)];if(!s)return;state.packing.push({id:id(),name:s.name,icon:s.icon,qty:1,weight:s.weight,bag:s.category,status:'needed',tripId:selectedTrip,notes:`Suggested: ${s.reason}`});save();toast('Added to inventory')},dismissPacking:({index})=>{const s=packingSuggestions()[Number(index)];if(!s)return;state.dismissed.push(s.name.toLowerCase());save()},});
function taskSuggestions(){const out=[];for(const d of state.destinations.filter(x=>x.status==='planned'||x.status==='booked')){for(const [title,category] of [[`Review transport to ${d.name}`,'transport'],[`Review stay in ${d.name}`,'accommodation']]){const key=`${d.id}:${category}`;if(!state.tasks.some(t=>t.suggestionKey===key)&&!state.dismissed.includes(key))out.push({key,title,category,tripId:d.tripId,destinationId:d.id})}}for(const s of state.skiTrips){const key=`ski:${s.id}`;if(!state.tasks.some(t=>t.suggestionKey===key)&&!state.dismissed.includes(key))out.push({key,title:`Review ski pass and rentals for ${s.resort}`,category:'skiing',tripId:s.tripId,destinationId:s.destinationId})}return out}
function tasksPage(){const all=state.tasks.filter(t=>(!filters.taskStatus||filters.taskStatus==='done'===!!t.done)&&(!filters.taskCategory||filters.taskCategory===t.category)&&(!filters.taskUrgency||filters.taskUrgency==='overdue'&&t.due&&days(t.due)<0||filters.taskUrgency==='upcoming'&&t.due&&days(t.due)>=0&&days(t.due)<=14)).sort((a,b)=>(a.done-b.done)||(a.due||'9999').localeCompare(b.due||'9999'));const suggests=taskSuggestions();return `${header('📜 Quest board','Small steps make big journeys','＋ New quest','newTask')}<div class="grid three"><div class="card soft-yellow"><strong>Explorer Lv. ${level()}</strong><p class="muted">${xp()} XP earned</p><div class="progress"><span style="width:${xp()%100}%"></span></div></div><div class="card soft-pink"><strong>${state.tasks.filter(x=>!x.done&&x.due&&days(x.due)<0).length} overdue quests</strong><p class="muted">Check deadlines when you are ready.</p></div><div class="card soft-blue"><strong>${state.tasks.filter(x=>x.done).length} completed quests</strong><p class="muted">Each completed quest awards 25 XP.</p></div></div><div class="toolbar"><select id="task-status" class="field" style="max-width:170px"><option value="">All statuses</option><option value="open" ${filters.taskStatus==='open'?'selected':''}>Open</option><option value="done" ${filters.taskStatus==='done'?'selected':''}>Completed</option></select><select id="task-category" class="field" style="max-width:240px"><option value="">All categories</option>${option(taskTypes,filters.taskCategory)}</select><select id="task-urgency" class="field" style="max-width:190px"><option value="">Any due date</option><option value="overdue" ${filters.taskUrgency==='overdue'?'selected':''}>Overdue</option><option value="upcoming" ${filters.taskUrgency==='upcoming'?'selected':''}>Next 14 days</option></select></div><div class="stack">${all.map(t=>`<div class="quest ${t.done?'done':''}"><input type="checkbox" data-task-check="${t.id}" ${t.done?'checked':''} aria-label="Complete ${esc(t.title)}"><div class="quest-main"><h3>${esc(t.title)}</h3><div class="row wrap"><span class="pill ${t.priority==='high'?'pink':t.priority==='low'?'gray':''}">${esc(t.priority||'normal')} priority</span><span class="pill yellow">${esc(t.category)}</span>${t.due?`<span class="small-text ${!t.done&&days(t.due)<0?'':'muted'}">📅 ${date(t.due)}${!t.done&&days(t.due)<0?' · overdue':''}</span>`:''}</div>${t.notes?`<p>${esc(t.notes)}</p>`:''}${t.subtasks?`<p>☑ ${esc(t.subtasks)}</p>`:''}<p>${esc(tripName(t.tripId))}${t.destinationId?' · '+esc(destName(t.destinationId)):''}${t.recurrence&&t.recurrence!=='none'?' · repeats '+esc(t.recurrence):''}</p></div><div class="quest-actions"><button class="btn small icon" data-action="editTask" data-id="${t.id}" aria-label="Edit quest">✎</button><button class="btn small icon" data-action="deleteTask" data-id="${t.id}" aria-label="Delete quest">🗑</button></div></div>`).join('')||'<div class="empty"><div class="big">📜</div>No quests match these filters.</div>'}</div>${header('✨ Suggested quests','Created only when you approve them')}<div class="grid two">${suggests.map((s,i)=>`<div class="suggestion"><strong>${esc(s.title)}</strong><p>Suggested because ${esc(destName(s.destinationId))} is in your plans.</p><div class="row"><button class="btn small primary" data-action="acceptTask" data-index="${i}">Accept quest</button><button class="btn small ghost" data-action="dismissTask" data-index="${i}">Dismiss</button></div></div>`).join('')||'<div class="empty" style="grid-column:1/-1">No new suggestions right now.</div>'}</div>`}
function taskForm(record){const t=record||{};modal(record?'Edit quest':'New quest',field('title','Quest title',t.title,'text','required')+selectField('category','Category',taskTypes,t.category||'personal')+selectField('priority','Priority',['low','normal','high'],t.priority||'normal')+field('due','Deadline',t.due,'date')+selectField('tripId','Trip',state.trips,t.tripId||selectedTrip)+selectField('destinationId','Destination',[{id:'',name:'None'},...state.destinations],t.destinationId||'')+selectField('recurrence','Repeat',['none','weekly','monthly'],t.recurrence||'none')+textField('subtasks','Subtasks (one per line)',t.subtasks)+textField('notes','Notes',t.notes),v=>{if(record)Object.assign(record,v);else state.tasks.push({id:id(),done:false,...v})})}
Object.assign(actions,{newTask:()=>taskForm(),editTask:({id})=>taskForm(state.tasks.find(x=>x.id===id)),deleteTask:({id})=>confirmDelete('tasks',id,'quest'),acceptTask:({index})=>{const s=taskSuggestions()[Number(index)];if(!s)return;state.tasks.push({id:id(),title:s.title,category:s.category,priority:'normal',due:'',tripId:s.tripId,destinationId:s.destinationId,done:false,suggestionKey:s.key,recurrence:'none'});save();toast('Quest accepted')},dismissTask:({index})=>{const s=taskSuggestions()[Number(index)];if(!s)return;state.dismissed.push(s.key);save()}});
function expenseBase(e){const base=state.profile.baseCurrency;if(e.currency===base)return Number(e.amount)||0;if(e.baseAmount!=null&&e.baseCurrency===base)return Number(e.baseAmount);return null}
function convertedExpenses(){let sum=0,unconverted=0;for(const e of state.expenses.filter(x=>x.kind==='actual')){const n=expenseBase(e);if(n==null)unconverted++;else sum+=n}return {sum,unconverted}}
function budgetPage(){const base=state.profile.baseCurrency,actual=convertedExpenses(),budget=Number(state.profile.exchangeBudget)||0,estimated=state.expenses.filter(x=>x.kind==='estimated').reduce((s,x)=>s+(expenseBase(x)||0),0),committed=state.expenses.filter(x=>x.kind==='committed').reduce((s,x)=>s+(expenseBase(x)||0),0);const byCat=Object.entries(state.expenses.filter(x=>x.kind==='actual').reduce((o,e)=>(o[e.category]=(o[e.category]||0)+(expenseBase(e)||0),o),{})).sort((a,b)=>b[1]-a[1]);return `${header('💰 Budget & expenses','Keep estimates, commitments, and actual spending distinct','＋ Add expense','newExpense')}<div class="notice">Amounts in other currencies count toward totals only after a conversion rate is saved. Original amounts and rates stay with each expense. ${actual.unconverted?`<strong>${actual.unconverted} actual expense(s) await conversion.</strong>`:''}</div><div class="grid four" style="margin-top:16px"><div class="card stat"><div class="stat-label">Exchange budget</div><div class="stat-value" style="font-size:19px">${budget?money(budget,base):'Not set'}</div><button class="btn small" data-action="setBudget">Set budget</button></div><div class="card stat"><div class="stat-label">Estimated</div><div class="stat-value" style="font-size:19px">${money(estimated,base)}</div></div><div class="card stat"><div class="stat-label">Committed</div><div class="stat-value" style="font-size:19px">${money(committed,base)}</div></div><div class="card stat"><div class="stat-label">Actual</div><div class="stat-value" style="font-size:19px">${money(actual.sum,base)}</div><div class="stat-note">${budget&&actual.sum>budget?'⚠️ Over budget':budget?`${Math.round(actual.sum/budget*100)}% of budget`:'No budget set'}</div></div></div>${header('📊 Spending picture','Actual expenses by category')}<div class="grid two"><div class="card"><div class="bar-chart">${byCat.map(([cat,n])=>`<div class="bar-row"><strong>${esc(cat)}</strong><div class="track"><span style="width:${pct(n,Math.max(...byCat.map(x=>x[1])))}%"></span></div><span>${money(n,base)}</span></div>`).join('')||'<div class="empty">Charts appear after you record actual expenses.</div>'}</div></div><div class="card soft-blue"><h3>💱 Exchange rates</h3><p class="muted">${state.ratesUpdated?`Rates fetched ${new Date(state.ratesUpdated).toLocaleString('en-SG')}`:'No live rates saved yet.'}</p><button class="btn small" data-action="refreshRates">Refresh live rates</button><p class="small-text muted">Source: open.er-api.com. If unavailable, existing recorded conversions remain unchanged.</p></div></div>${header('🧾 Expense ledger','One record per expense; linked bookings are never counted twice','Export CSV','exportCSV')}<div class="card"><div class="toolbar"><select id="expense-kind" class="field" style="max-width:180px"><option value="">All stages</option>${option(['estimated','committed','actual'],filters.expenseKind)}</select><select id="expense-category" class="field" style="max-width:190px"><option value="">All categories</option>${option(expenseTypes,filters.expenseCategory)}</select></div>${state.expenses.filter(e=>(!filters.expenseKind||e.kind===filters.expenseKind)&&(!filters.expenseCategory||e.category===filters.expenseCategory)).map(e=>`<div class="list-row"><div><strong>${esc(e.title)}</strong><small>${esc(e.category)} · ${esc(e.kind)} · ${date(e.date)} · ${esc(destName(e.destinationId))}${e.sourceBookingId?' · linked booking':''}</small></div><div class="row"><strong>${money(e.amount,e.currency)}</strong><button class="btn small icon" data-action="editExpense" data-id="${e.id}" aria-label="Edit expense">✎</button><button class="btn small icon" data-action="deleteExpense" data-id="${e.id}" aria-label="Delete expense">🗑</button></div></div>`).join('')||'<div class="empty">No expenses yet.</div>'}</div>`}
function expenseForm(record){const e=record||{};modal(record?'Edit expense':'Add expense',field('title','Description',e.title,'text','required')+selectField('category','Category',expenseTypes,e.category||'miscellaneous')+selectField('kind','Stage',['estimated','committed','actual'],e.kind||'actual')+field('amount','Amount',e.amount,'number','min="0" step="0.01" required')+selectField('currency','Currency',currencies,e.currency||state.profile.baseCurrency)+field('date','Date',e.date||today(),'date')+selectField('tripId','Trip',state.trips,e.tripId||selectedTrip)+selectField('destinationId','Destination',[{id:'',name:'None'},...state.destinations],e.destinationId||'')+selectField('payment','Payment',['unpaid','prepaid','paid'],e.payment||'unpaid')+textField('notes','Notes',e.notes),v=>{const n=Number(v.amount);if(!Number.isFinite(n)||n<0)throw Error('Enter a valid amount');const rate=v.currency===state.profile.baseCurrency?1:state.rates?.[v.currency]?1/state.rates[v.currency]:null;const conversion={baseAmount:rate==null?null:Math.round(n*rate*100)/100,conversionRate:rate,baseCurrency:state.profile.baseCurrency,rateTimestamp:rate==null?null:state.ratesUpdated};if(record)Object.assign(record,v,conversion);else state.expenses.push({id:id(),...v,...conversion})})}
Object.assign(actions,{newExpense:()=>expenseForm(),editExpense:({id})=>expenseForm(state.expenses.find(x=>x.id===id)),deleteExpense:({id})=>confirmDelete('expenses',id,'expense'),setBudget:()=>modal('Set exchange budget',field('exchangeBudget',`Budget (${state.profile.baseCurrency})`,state.profile.exchangeBudget,'number','min="0" step="0.01"'),v=>{state.profile.exchangeBudget=v.exchangeBudget}),refreshRates:async()=>{try{const r=await fetch(`https://open.er-api.com/v6/latest/${state.profile.baseCurrency}`);const j=await r.json();if(j.result!=='success')throw Error();state.rates=j.rates;state.ratesUpdated=new Date().toISOString();save();toast('Live rates updated')}catch{toast('Live rates unavailable. Existing conversions were kept.')}},exportCSV:()=>{const rows=[['Description','Category','Stage','Amount','Currency','Base amount','Base currency','Rate used','Rate timestamp','Date','Destination','Payment'],...state.expenses.map(e=>[e.title,e.category,e.kind,e.amount,e.currency,e.baseAmount,e.baseCurrency,e.conversionRate,e.rateTimestamp,e.date,destName(e.destinationId),e.payment])];download('pixel-passport-expenses.csv',rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n'),'text/csv')}});
function bookingsPage(){return `${header('🎫 Booking vault','Keep references, links, and dates in one cozy place','＋ Add booking','newBooking')}<div class="notice">Booking records are entered by you. Nothing shown here is a confirmed reservation unless you mark it confirmed.</div><div class="toolbar"><select id="booking-type" class="field" style="max-width:210px"><option value="">All booking types</option>${option(['flight','train','hotel','hostel','ski pass','equipment rental','attraction','other'],filters.bookingType)}</select><select id="booking-status" class="field" style="max-width:190px"><option value="">All statuses</option>${option(['idea','reserved','confirmed','cancelled'],filters.bookingStatus)}</select></div><div class="grid three">${state.bookings.filter(b=>(!filters.bookingType||b.type===filters.bookingType)&&(!filters.bookingStatus||b.status===filters.bookingStatus)).map(b=>`<div class="card"><div class="row between"><span class="place-icon">${{flight:'✈️',train:'🚆',hotel:'🏨',hostel:'🛏️','ski pass':'⛷️'}[b.type]||'🎫'}</span><span class="pill ${b.status==='confirmed'?'':'yellow'}">${esc(b.status)}</span></div><h3>${esc(b.provider||b.type)}</h3><p class="muted small-text">${esc(b.type)} · ${esc(destName(b.destinationId))}<br>${date(b.date)} ${esc(b.time||'')}</p><p><strong>Reference:</strong> ${esc(b.reference||'Not entered')}</p><p>${b.cost?money(b.cost,b.currency):'Cost not entered'}${b.expenseId?' · linked expense':''}</p><div class="row wrap"><button class="btn small" data-action="editBooking" data-id="${b.id}">Edit</button><button class="btn small icon" data-action="deleteBooking" data-id="${b.id}" aria-label="Delete booking">🗑</button>${b.link?`<a class="btn small ghost" href="${esc(b.link)}" target="_blank" rel="noopener noreferrer">Open link ↗</a>`:''}</div></div>`).join('')||'<div class="empty" style="grid-column:1/-1">No bookings recorded yet. Add your first reservation when you have the details.</div>'}</div>`}
function bookingForm(record,destinationId){const b=record||{};modal(record?'Edit booking':'Add booking',selectField('type','Type',['flight','train','hotel','hostel','ski pass','equipment rental','attraction','other'],b.type||'train')+selectField('status','Status',['idea','reserved','confirmed','cancelled'],b.status||'idea')+field('provider','Provider',b.provider)+field('reference','Booking reference',b.reference)+field('date','Date',b.date,'date')+field('time','Time',b.time,'time')+selectField('tripId','Trip',state.trips,b.tripId||selectedTrip)+selectField('destinationId','Destination',[{id:'',name:'None'},...state.destinations],b.destinationId||destinationId||'')+field('cost','Cost',b.cost,'number','min="0" step="0.01"')+selectField('currency','Currency',currencies,b.currency||state.profile.baseCurrency)+field('link','Booking link',b.link,'url')+selectField('expenseId','Linked expense',[{id:'',name:'None'},...state.expenses.map(e=>({id:e.id,name:`${e.title} · ${money(e.amount,e.currency)}`}))],b.expenseId||'')+textField('notes','Notes',b.notes)+`<div class="full notice">Link an existing expense to avoid double counting. To record a new cost in your budget, add an expense separately.</div>`,v=>{if(record)Object.assign(record,v);else state.bookings.push({id:id(),...v})})}
Object.assign(actions,{newBooking:({destination})=>bookingForm(null,destination),editBooking:({id})=>bookingForm(state.bookings.find(x=>x.id===id)),deleteBooking:({id})=>confirmDelete('bookings',id,'booking')});
function skiPage(){return `<div class="snow-banner"><div class="eyebrow">❄️ THE SNOW TRAIL ❄️</div><h2 class="section-title">Ski planner</h2><p>Plan a mountain day, then see new equipment and quest suggestions appear.</p></div>${header('⛷️ Mountain adventures','Ski plans link to destinations and packing','＋ New ski plan','newSki')}<div class="grid three">${state.skiTrips.map(s=>`<div class="card soft-blue"><div style="font-size:36px">🏔️</div><h3>${esc(s.resort)}</h3><p class="muted">${esc(s.country)} · ${date(s.start)} – ${date(s.end)}</p><p><span class="pill">${esc(s.level)} level</span></p><p class="small-text">Pass: ${s.passCost?money(s.passCost,s.currency):'Not entered'} · Rental: ${s.rentalCost?money(s.rentalCost,s.currency):'Not entered'}</p><p class="muted small-text">${esc(s.notes||'No notes yet')}</p><div class="row"><button class="btn small" data-action="editSki" data-id="${s.id}">Edit plan</button><button class="btn small icon" data-action="deleteSki" data-id="${s.id}" aria-label="Delete ski plan">🗑</button></div></div>`).join('')||'<div class="empty" style="grid-column:1/-1">No mountain plans yet. Add a resort to start preparing.</div>'}</div>${header('🎿 Equipment checklist','Review suggestions in Packing Inventory')}<div class="card"><p class="muted">Ski jacket and pants · thermal layers · waterproof gloves · goggles · ski socks · helmet or rental reminder</p><button class="btn small primary" data-action="goPacking">Open packing inventory →</button></div>`}
function skiForm(record){const s=record||{};modal(record?'Edit ski plan':'New ski plan',field('resort','Resort or mountain',s.resort,'text','required')+field('country','Country',s.country,'text','required')+selectField('tripId','Trip',state.trips,s.tripId||selectedTrip)+selectField('destinationId','Linked destination',[{id:'',name:'None yet'},...state.destinations],s.destinationId||'')+field('start','First ski date',s.start,'date')+field('end','Last ski date',s.end,'date')+selectField('level','Experience level',['beginner','intermediate','advanced'],s.level||'beginner')+field('passCost','Ski pass estimate',s.passCost,'number','min="0" step="0.01"')+field('rentalCost','Rental estimate',s.rentalCost,'number','min="0" step="0.01"')+selectField('currency','Currency',currencies,s.currency||'CHF')+field('transport','Transport plan',s.transport)+textField('equipment','Equipment / wishlist',s.equipment)+textField('notes','Notes',s.notes)+`<div class="full notice">Add a linked destination to place this ski plan on your map. Costs here are planning notes; add an expense to track them in the budget.</div>`,v=>{if(v.start&&v.end&&v.end<v.start)throw Error('End date must be after start date');if(record)Object.assign(record,v);else state.skiTrips.push({id:id(),...v})})}
Object.assign(actions,{newSki:()=>skiForm(),editSki:({id})=>skiForm(state.skiTrips.find(x=>x.id===id)),deleteSki:({id})=>confirmDelete('skiTrips',id,'ski plan')});
function journalPage(){const stamps=[...new Set(state.destinations.filter(x=>x.status==='visited').map(x=>x.country))];return `${header('📖 Travel journal','The little moments are the best souvenirs','＋ New entry','newJournal')}<div class="grid three"><div class="card soft-pink"><strong>${state.journal.length} memories</strong><p class="muted">Words, pictures and favorite places.</p></div><div class="card soft-lav"><strong>${stamps.length} country stamps</strong><p class="muted">Unlocked by visited destinations.</p></div><div class="card soft-yellow"><strong>${state.destinations.filter(x=>x.status==='visited').length} visited stops</strong><p class="muted">Your adventure history is growing.</p></div></div>${header('✦ Memories','Newest entries first')}<div class="grid two">${[...state.journal].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(j=>`<article class="journal-page">${j.photo?`<img src="${esc(j.photo)}" alt="${esc(j.caption||'Travel memory')}" style="width:100%;max-height:250px;object-fit:cover;border-radius:6px;margin-bottom:10px">`:'<div style="font-size:40px">📷</div>'}<div class="muted small-text">${date(j.date)} · ${esc(destName(j.destinationId))}</div><h3>${esc(j.title)}</h3><p>${esc(j.body)}</p>${j.caption?`<p class="muted small-text">${esc(j.caption)}</p>`:''}<div class="row"><span class="pill ${j.favorite?'pink':'gray'}">${j.favorite?'♥ Favorite':'Memory'}</span><button class="btn small" data-action="editJournal" data-id="${j.id}">Edit</button><button class="btn small icon" data-action="deleteJournal" data-id="${j.id}" aria-label="Delete entry">🗑</button></div></article>`).join('')||'<div class="empty" style="grid-column:1/-1"><div class="big">📖</div>Your diary is waiting for its first story.</div>'}</div>${header('📘 Passport stamps','Mark a destination visited to earn a stamp')}<div class="stamp-grid">${stamps.map(c=>`<div class="stamp"><div><span>✦</span><strong>${esc(c)}</strong></div></div>`).join('')||'<div class="empty" style="grid-column:1/-1">No stamps yet — adventures ahead!</div>'}</div>`}
function journalForm(record){const j=record||{};modal(record?'Edit memory':'New memory',field('title','Entry title',j.title,'text','required')+field('date','Date',j.date||today(),'date')+selectField('destinationId','Place',[{id:'',name:'None'},...state.destinations],j.destinationId||'')+field('caption','Photo caption',j.caption)+`<label class="full">Photo (saved on this device; under 1 MB)<input class="field" name="photoFile" type="file" accept="image/*"></label>`+textField('body','Your memory',j.body,6)+`<label class="full"><input name="favorite" type="checkbox" ${j.favorite?'checked':''}> Favorite place</label>`,async v=>{const file=$('#dialog-form').elements.photoFile.files[0];let photo=j.photo||'';if(file){if(file.size>1000000)throw Error('Choose a photo under 1 MB for local storage');photo=await new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}const data={title:v.title,date:v.date,destinationId:v.destinationId,caption:v.caption,body:v.body,favorite:v.favorite==='on',photo};if(record)Object.assign(record,data);else state.journal.push({id:id(),...data})})}
Object.assign(actions,{newJournal:()=>journalForm(),editJournal:({id})=>journalForm(state.journal.find(x=>x.id===id)),deleteJournal:({id})=>confirmDelete('journal',id,'journal entry')});
function settingsPage(){return `${header('⚙️ Settings','Make this little world yours')}<div class="settings-list"><div class="card"><h3>🧑‍✈️ Traveler profile</h3><div class="form-grid">${field('profileName','Your name',state.profile.name)+selectField('baseCurrency','Base currency',currencies,state.profile.baseCurrency)+field('weightTarget','Luggage weight target (kg)',state.profile.weightTarget,'number','min="0" step="0.1"')}</div><p><button class="btn primary" data-action="saveProfile">Save profile</button></p></div><div class="card soft-blue"><h3>💾 Your data</h3><p class="muted">Demo mode saves to this browser on this device. Export a backup before clearing browser data or moving devices.</p><div class="row wrap"><button class="btn small" data-action="exportJSON">Export backup</button><label class="btn small">Import backup<input id="import-file" type="file" accept="application/json" hidden></label><button class="btn small danger" data-action="resetData">Reset demo data</button></div></div><div class="card soft-yellow"><h3>🔌 Connected services</h3><p><strong>Working now:</strong> OpenStreetMap map tiles, Open-Meteo current weather, city lookup, and live exchange-rate fetch when reachable.</p><p class="muted">Supabase authentication, cloud database, document uploads and long-term synced storage require credentials and backend configuration. This release uses device-local demo storage.</p></div><div class="card"><h3>⌨️ Accessibility</h3><p class="muted">All navigation, forms and actions are keyboard accessible. Destructive actions ask for confirmation.</p></div></div>`}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
Object.assign(actions,{saveProfile:()=>{const name=$('[name=profileName]').value.trim(),base=$('[name=baseCurrency]').value;if(!name)return toast('Enter your name');state.profile.name=name;state.profile.baseCurrency=base;state.profile.weightTarget=$('[name=weightTarget]').value;save();toast('Profile saved')},exportJSON:()=>download('pixel-passport-backup.json',JSON.stringify(state,null,2),'application/json'),resetData:()=>{if(confirm('Reset all demo data? Export a backup first if you want to keep your plans.')){state=seed();selectedTrip=state.trips[0].id;save();toast('Demo data reset')}}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='trip-select'){selectedTrip=el.value;selectedDestination=null;render()}else if(el.id==='activity-type-filter'){filters.activityType=el.value;render()}else if(el.id==='activity-status-filter'){filters.activityStatus=el.value;render()}else if(el.id==='map-trip'){filters.mapTrip=el.value;render()}else if(el.id==='map-status'){filters.mapStatus=el.value;render()}else if(el.id==='pack-bag'){filters.packBag=el.value;render()}else if(el.id==='pack-status'){filters.packStatus=el.value;render()}else if(el.id==='task-status'){filters.taskStatus=el.value;render()}else if(el.id==='task-category'){filters.taskCategory=el.value;render()}else if(el.id==='task-urgency'){filters.taskUrgency=el.value;render()}else if(el.id==='expense-kind'){filters.expenseKind=el.value;render()}else if(el.id==='expense-category'){filters.expenseCategory=el.value;render()}else if(el.id==='booking-type'){filters.bookingType=el.value;render()}else if(el.id==='booking-status'){filters.bookingStatus=el.value;render()}else if(el.dataset.packCheck){const p=state.packing.find(x=>x.id===el.dataset.packCheck);p.status=el.checked?'packed':'needed';save();if(el.checked)toast('Item packed! ✨')}else if(el.dataset.taskCheck){const t=state.tasks.find(x=>x.id===el.dataset.taskCheck);t.done=el.checked;if(t.done&&t.recurrence&&t.recurrence!=='none'&&t.due){const next=new Date(`${t.due}T12:00:00`);if(t.recurrence==='weekly')next.setDate(next.getDate()+7);else next.setMonth(next.getMonth()+1);state.tasks.push({...t,id:id(),done:false,due:next.toISOString().slice(0,10),suggestionKey:''})}save();if(el.checked)toast('Quest complete! +25 XP ✨')}else if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text());for(const key of ['trips','destinations','activities','tasks','packing','expenses','bookings','skiTrips','journal'])if(!Array.isArray(parsed[key]))throw Error('Invalid backup structure');if(!confirm('Replace current demo data with this backup?'))return;state=parsed;selectedTrip=state.trips[0]?.id;save();toast('Backup imported')}catch(err){toast(err.message||'Could not import backup')}}});
let dragging=null;document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag-activity]');if(row)dragging=row.dataset.dragActivity});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drag-activity]'))e.preventDefault()});document.addEventListener('drop',e=>{const row=e.target.closest('[data-drag-activity]');if(!row||!dragging||row.dataset.dragActivity===dragging)return;e.preventDefault();const a=state.activities.find(x=>x.id===dragging),b=state.activities.find(x=>x.id===row.dataset.dragActivity);if(a.destinationId!==b.destinationId)return;[a.order,b.order]=[b.order,a.order];dragging=null;save();toast('Activity reordered')});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.id==='map-search'){e.preventDefault();actions.searchMap()}});
render();
